import React from "react";
import Home from "./components/Home/Home";
import Header from "./components/Header";
import deviteslogo from './assets/deviteslogo.png'; // Replace with the actual path to your assets/deviteslogo.png';
import "./App.css";

function App() {
  useEffect(() => {
    const script = document.createElement('script');
    script.src = '//s3.amazonaws.com/downloads.mailchimp.com/js/mc-validate.js';
    script.type = 'text/javascript';
    script.async = true;
    document.body.appendChild(script);

    script.onload = () => {
      window.fnames = [];
      window.ftypes = [];
      window.fnames[0] = 'EMAIL';
      window.ftypes[0] = 'email';
    };

    return () => {
      document.body.removeChild(script);
    };
  }, []);
  return (
    <div className="main-wrapper">
      <Header />
      <Home />
      <div className="f-footer-glow">
  <div className="footer-columns">

    <div className="footer-links">
      <img src={deviteslogo} alt="deviteslogo" style={{ maxWidth: '15vw', minWidth: '106px', height: 'auto', opacity: '0.2'}}/>
    </div>


    <div className="footer-newsletter">
      <h4>Sign Up For Our Newsletter Today.</h4>
      <div className="newsletter-input">
        <div id="mc_embed_signup">
      <form
        action="https://devitx.us19.list-manage.com/subscribe/post?u=14412fefabebc07ddd3db75bd&amp;id=21226cd91e&amp;f_id=000235e7f0"
        method="post"
        target="_blank"
        rel="noreferrer"
        noValidate
      >
        <h2>Subscribe</h2>
        <div className="indicates-required">
          <span className="asterisk">*</span> indicates required
        </div>
        <div className="mc-field-group">
          <label htmlFor="mce-EMAIL">
            Email Address <span className="asterisk">*</span>
          </label>
          <input type="email" name="EMAIL" className="required email" id="mce-EMAIL" required />
        </div>
        <div id="mce-responses" className="clear foot">
          <div className="response" id="mce-error-response" />
          <div className="response" id="mce-success-response" />
        </div>
        <div style={{ position: 'absolute', left: '-5000px' }} aria-hidden="true">
          <input type="text" name="b_14412fefabebc07ddd3db75bd_21226cd91e" tabIndex="-1" />
        </div>
        <div className="clear foot">
          <input type="submit" name="subscribe" id="mc-embedded-subscribe" className="button" value="Subscribe" />
        </div>
      </form>
    </div>
      </div>
    </div>


    <div className="footer-contact">
      <h4>Contact</h4>
      <p>business@devitx.com</p>
      <p>+91 8208835994</p>
<div className="social-icons-svg">
