      <path d="M22.46 6c-.77.35-1.5.6-2.28.7a3.9 3.9 0 0 0 1.7-2.1c-.8.5-1.6.8-2.5 1a4 4 0 0 0-6.8 3.6A11.4 11.4 0 0 1 3 5.2a4 4 0 0 0 1.3 5.3c-.6 0-1.1-.2-1.6-.4v.1a4 4 0 0 0 3.2 4 4.1 4.1 0 0 1-1.7.1 4 4 0 0 0 3.8 2.9A8 8 0 0 1 2 19.5a11.3 11.3 0 0 0 6.1 1.8c7.4 0 11.4-6.1 11.4-11.4v-.5a8.2 8.2 0 0 0 2-2.1z"/>
